INSERT INTO roles (id, slug, title, category, description, academic_requirements, career_outlook) VALUES
('b0000001-0000-0000-0000-000000000001', 'software-developer', 'Software Developer', 'Software Engineering', 'Designs, codes, tests, and maintains core software applications, algorithms, and system integrations using modern programming paradigms.', 'B.Tech/B.E/BCA/MCA in Computer Science or related engineering field.', 'High demand across IT services, product companies, and fintech.'),
('b0000001-0000-0000-0000-000000000002', 'frontend-developer', 'Frontend Developer', 'Web Development', 'Specializes in user interfaces, client-side web applications, reactive state management, and modern browser standards.', 'Computer Science, IT, or design-engineering background.', 'Strong demand for React, Next.js, and TypeScript developers.'),
('b0000001-0000-0000-0000-000000000003', 'backend-developer', 'Backend Developer', 'Software Engineering', 'Architects server-side logic, RESTful/GraphQL APIs, database persistence, caching, and scalable microservices.', 'Computer Science, Information Technology, or Software Engineering.', 'Crucial role in platform infrastructure, distributed systems, and SaaS.'),
('b0000001-0000-0000-0000-000000000004', 'fullstack-developer', 'Full-Stack Developer', 'Software Engineering', 'Bridges end-to-end web engineering, proficient in frontend client UX, backend services, and relational/NoSQL datastores.', 'B.Tech/B.E in CS/IT or equivalent.', 'Highly valued in startups, agile teams, and fast-paced tech firms.'),
('b0000001-0000-0000-0000-000000000005', 'data-analyst', 'Data Analyst', 'Data & Analytics', 'Extracts, cleans, analyzes, and visualizes structured datasets to guide business decision-making and operational strategy.', 'Degree in CS, Statistics, Mathematics, Economics, or Data Science.', 'Universal demand across finance, healthcare, e-commerce, and consulting.'),
('b0000001-0000-0000-0000-000000000006', 'data-scientist', 'Data Scientist', 'Data Science & AI', 'Applies statistical modeling, machine learning, and advanced feature engineering to discover predictive patterns in complex data.', 'Degree in Computer Science, Statistics, Mathematics, or Data Science.', 'Elite demand for data-driven modeling and experimental AI.'),
('b0000001-0000-0000-0000-000000000007', 'ml-engineer', 'Machine Learning Engineer', 'Artificial Intelligence', 'Bridges data science and production engineering, deploying, scaling, and monitoring deep learning and ML pipelines in production.', 'B.Tech/M.Tech in CS/AI/ML with strong programming fundamentals.', 'Fastest-growing tech role with AI and LLM enterprise adoption.'),
('b0000001-0000-0000-0000-000000000008', 'devops-engineer', 'DevOps Engineer', 'Infrastructure & Cloud', 'Automates CI/CD deployment pipelines, container orchestration, infrastructure as code, and system reliability monitoring.', 'CS/IT engineering degree with strong Linux and networking grounding.', 'Essential for modern agile organizations and cloud delivery.'),
('b0000001-0000-0000-0000-000000000009', 'cloud-engineer', 'Cloud Engineer', 'Cloud Infrastructure', 'Designs and administers cloud architectures on AWS/Azure/GCP, ensuring high availability, security, and cost efficiency.', 'Engineering degree in Computer Science, IT, or Electronics.', 'Rapidly expanding market with massive enterprise cloud migration.'),
('b0000001-0000-0000-0000-000000001010', 'cybersecurity-analyst', 'Cybersecurity Analyst', 'Security', 'Protects systems, networks, and data assets against unauthorized access, conducting vulnerability analysis and threat mitigation.', 'CS, Cybersecurity, Information Assurance, or IT degree.', 'Critical global shortage of qualified cybersecurity talent.'),
('b0000001-0000-0000-0000-000000001011', 'qa-engineer', 'QA / Test Engineer', 'Quality Assurance', 'Validates software quality through test automation suites, performance testing, regression suites, and bug lifecycle tracking.', 'Computer Science or Engineering degree.', 'Standard requirement in software delivery teams focusing on automated testing.'),
('b0000001-0000-0000-0000-000000001012', 'business-analyst', 'Business Analyst', 'Product & Analytics', 'Translates business goals into technical specifications, user stories, workflows, and acceptance criteria for engineering teams.', 'B.Tech, MBA, BCA/MCA, or relevant multidisciplinary degree.', 'High demand across enterprise technology, banking, and consulting.'),
('b0000001-0000-0000-0000-000000001013', 'database-administrator', 'Database Administrator', 'Database Engineering', 'Manages database integrity, performance indexing, replication, high availability, backup recovery, and SQL query tuning.', 'CS/IT or related computing discipline.', 'Core role in financial services, enterprise ERP, and big data architectures.'),
('b0000001-0000-0000-0000-000000001014', 'ui-ux-designer', 'UI/UX Designer', 'Design & UX', 'Researches user behavior, creates wireframes, interactive Figma prototypes, and design systems for intuitive user journeys.', 'Design, Human-Computer Interaction, CS, or Multimedia.', 'High importance for user-centric digital products and SaaS applications.'),
('b0000001-0000-0000-0000-000000001015', 'systems-engineer', 'Technical Support / Systems Engineer', 'IT Operations', 'Maintains workstation and server infrastructure, network topology, troubleshooting, operating systems, and client support.', 'Degree or Diploma in CS, IT, Electronics, or Computer Applications.', 'Steady baseline demand across corporate IT infrastructure.')
